{"implementation": "def solve(case):
    edges = case['edges']
    refinement = case['refinement']
    group_members = {}
    for node, group in refinement.items():
        group_members.setdefault(group, []).append(node)
    for group in group_members:
        group_members[group].sort()
    agg = {}
    for (u, v, w) in edges:
        g_u = refinement[u]
        g_v = refinement[v]
        key = tuple(sorted((g_u, g_v)))
        agg[key] = agg.get(key, 0) + w
    sorted_edges = sorted([list(k) + [v] for k, v in agg.items()], key=lambda x: (x[0], x[1]))
    return {"aggregate_edges": sorted_edges, "members": group_members}
"}
